var supersede = (request2, env) => runCaseScript("supersede_draft", "generate", request2, env);
function generatorSql(matterRoot, generator, env = process.env) {
  const command = generator?.args?.command;
  const allowed = Object.hasOwn(ALLOWED, generator?.script) ? ALLOWED[generator.script] : [];
  if (typeof command !== "string" || !allowed.includes(command)) {
    throw new ValidationError(`generator must be an allowlisted script and command: ${Object.entries(ALLOWED).map(([s3, c3]) => `${s3} ${c3.join(" or ")}`).join("; ")}`);
  }
  if (command === "rehash-sql") return supersede(generator.args, env);
  const { superseded, kept } = generator.args;
  const registered = [superseded, kept].filter((s3) => typeof s3 === "number");
  if (registered.length !== 1) {
    throw new ValidationError("the generator runs only when one side of the pair has no row: name one source_id and one {file_path, file_hash}");
  }
  const probe2 = supersede({ command: "probe" }, env);
  const rows4 = caseDataQuery(matterRoot, probe2, [JSON.stringify(registered)]).rows;
  const id = (s3) => typeof s3 === "number" ? s3 : null;
  const plan2 = supersede({ command: "fold-plan", rows: rows4, superseded: id(superseded), kept: id(kept) }, env);
  const notes = Object.fromEntries(rows4.filter((r3) => r3.kind === "source" && r3.id === registered[0]).map((r3) => [String(r3.id), r3.notes]));
  const today3 = caseDataQuery(matterRoot, "SELECT date('now','localtime') AS today").rows[0].today;
  const facts = [...plan2.auto.map((f3) => ({ fact_id: f3.fact_id, fold_into: f3.fold_into })), ...plan2.agent_required.map((f3) => ({ fact_id: f3.fact_id }))];
  return supersede({
    command: "emit-sql",
    outcome: "superseded",
    superseded,
    kept,
    notes,
    execution_status: generator.args.execution_status ?? {},
    children_into: plan2.children_into,
    facts,
    date: today3,
    approver: generator.args.approver
  }, env);
}

